#include <cstdint>
#include "address.h"
#include "modules.h"

struct gen_aggressive_offset_s0 : public champsim::modules::prefetcher {
    using prefetcher::prefetcher;

    static constexpr uint32_t REGION_SIZE = 8;
    static constexpr uint32_t MAX_OFFSET = 4;
    static constexpr uint32_t CONFIDENCE_THRESHOLD = 2;

    uint8_t region_confidences[1 << 14] = {0}; // 2^14 regions (64KB/8-line regions)

    uint32_t prefetcher_cache_operate(champsim::address addr, champsim::address ip,
                                     uint8_t cache_hit, bool useful_prefetch,
                                     access_type type, uint32_t metadata_in) {
        uint64_t region = (addr >> LOG2_BLOCK_SIZE) / REGION_SIZE;
        uint64_t offset = (addr >> LOG2_BLOCK_SIZE) % REGION_SIZE;

        if (region_confidences[region] >= CONFIDENCE_THRESHOLD) {
            for (uint32_t i = 1; i <= MAX_OFFSET; ++i) {
                champsim::address pf_addr = addr + (i << LOG2_BLOCK_SIZE);
                prefetch_line(pf_addr, 0, true);
            }
        }

        return metadata_in;
    }

    uint32_t prefetcher_cache_fill(champsim::address addr, long set, long way,
                                  uint8_t prefetch, champsim::address evicted_addr,
                                  uint32_t metadata_in) {
        uint64_t region = (addr >> LOG2_BLOCK_SIZE) / REGION_SIZE;
        if (prefetch) {
            if (region_confidences[region] < 3) {
                region_confidences[region]++;
            }
        } else {
            if (region_confidences[region] > 0) {
                region_confidences[region]--;
            }
        }
        return metadata_in;
    }
};

